@startuml

class Song {
  + Title : string
  + Year : int
  + Length : double
  + Genre : string
}

class Artist {
  + Name : string
  + BirthDate : date
  + Website : string
}

class User {
  + UserID : int
  + Name : string
  + Address : string
}

abstract class UserType {
  + VATNumber : string
}

class RegularUser {}

class BusinessUser {
  + Singles : Song[]
  + Albums : Album[]
}

class Hit {
  + TrackNumber : int
}

class Album {
  + Hits : Hit[]
}

Song "1" -- "1" Artist
User "1" -- "*" UserType
RegularUser ..|> UserType
BusinessUser ..|> UserType
BusinessUser "1..*" Song
Album "1" -- "*" Hit

@enduml

